@Timeout(90)
class LmdbBackupOutboxFootprintTest {

	private static final int STAGES = 64;

	@Test
	void smallUnpublishedStagesUseAtMostEightSourcePages(@TempDir Path directory) throws Exception {
		Path live = directory.resolve("live");
		Path backups = directory.resolve("backups");
		LmdbStoreConfig config = new LmdbStoreConfig().setBackupJournalEnabled(true);
		LmdbStore store = new LmdbStore(live.toFile(), config);
		CountDownLatch selected = new CountDownLatch(1);
		CountDownLatch release = new CountDownLatch(1);
		List<Statement> statements = new ArrayList<>();
		Map<Long, byte[]> expectedStages = new LinkedHashMap<>();
		long baseline;
		long head;
		UUID identity;
		UUID generation;
		Footprint footprint;
		store.init();
		try {
			baseline = store.getBackupService()
					.createBackup(BackupRequest.builder(backups, BackupType.FULL).build())
					.getEndTransactionId();
			generation = store.getBackingStore().backupJournalState().generation();
			TripleStore triples = store.getBackingStore().getTripleStore();
			UUID predecessor = triples.getBackupOutboxHead();
			PostCommitBackupPublisher publisher = store.getBackingStore().backupPublisher();
			publisher.setBeforePublication(() -> {
				selected.countDown();
				try {
					assertTrue(release.await(60, TimeUnit.SECONDS), "The test must release the stopped publisher");
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError(interrupted);
				}
			});

			for (int index = 0; index < STAGES; index++) {
				Statement statement = statement(index);
				statements.add(statement);
				add(store, statement);
				if (index == 0) {
					assertTrue(selected.await(20, TimeUnit.SECONDS),
							"The first real commit must pause before archive publication");
				}
				long transaction = baseline + index + 1;
				byte[] actual;
				try (var input = triples.openBackupStage(transaction)) {
					actual = input.readAllBytes();
				}
				Stage stage;
				try (var input = new DataInputStream(new ByteArrayInputStream(actual))) {
					stage = PostCommitBackupPublisher.readStage(input, null);
				}
				assertEquals(transaction, stage.transaction);
				assertEquals(transaction - 1, stage.previousTransaction);
				assertEquals(predecessor, stage.predecessor);
				assertEquals(1, stage.count);
				byte[] expected = stageBytes(stage, statement);
				assertArrayEquals(expected, actual,
						"Every native stage must contain the exact committed statement and real predecessor");
				expectedStages.put(transaction, expected);
				predecessor = stage.id;
			}

			head = baseline + STAGES;
			identity = predecessor;
			assertEquals(LongStream.rangeClosed(baseline + 1, head).boxed().toList(),
					triples.listBackupStageTransactions(baseline, Long.MAX_VALUE));
			assertEquals(head, triples.getRequiredBackupTxnId());
			assertEquals(identity, triples.getBackupOutboxHead());
			assertEquals(baseline, publisher.acknowledgedTransactionId(),
					"All measured stages must still be unpublished and ineligible for reclamation");
			footprint = footprint(triples);
			assertFalse(footprint.databases().isEmpty());
			assertTrue(footprint.entries() > 0);
			long rawBytes = expectedStages.values().stream().mapToLong(bytes -> bytes.length).sum();
			// Allow 16 bytes per native entry for leaf-node/index/alignment overhead, and reserve 64 bytes
			// per page. These actual key/value bytes fit three leaves; eight total pages allows twice that
			// leaf space, a root branch and one spare page without prescribing a database count or routing.
			long packedBytes = footprint.keyValueBytes() + 16 * footprint.entries();
			assertTrue(packedBytes <= 3L * (footprint.pageSize() - 64),
					"The fixture must remain small enough to justify its eight-page storage bound");
			System.out.printf("Source footprint: stages=%d rawBytes=%d keyValueBytes=%d entries=%d pageSize=%d "
					+ "leafPages=%d branchPages=%d overflowPages=%d databases=%s%n", STAGES, rawBytes,
					footprint.keyValueBytes(), footprint.entries(), footprint.pageSize(), footprint.leafPages(),
					footprint.branchPages(), footprint.overflowPages(), footprint.databases());

			release.countDown();
			publisher.close();
			assertEquals(head, publisher.acknowledgedTransactionId());
			assertEquals(identity, publisher.acknowledgement().identity());
			assertPublished(store, backups, baseline, generation, statements, directory.resolve("exported"));
			assertContents(store, statements);
		} finally {
			release.countDown();
			store.shutDown();
		}

		LmdbStore reopened = new LmdbStore(live.toFile(), config);
		reopened.init();
		try {
			TripleStore triples = reopened.getBackingStore().getTripleStore();
			assertEquals(head, triples.getRequiredBackupTxnId());
			assertEquals(identity, triples.getBackupOutboxHead());
			assertNotNull(triples.readBackupStageHeader(head));
			try (var input = triples.openBackupStage(head)) {
				assertArrayEquals(expectedStages.get(head), input.readAllBytes(),
						"The latest native stage must remain authoritative across reopen");
			}
			assertPublished(reopened, backups, baseline, generation, statements,
					directory.resolve("reopened-export"));
			assertContents(reopened, statements);
		} finally {
			reopened.shutDown();
		}

		assertEquals(0L, footprint.overflowPages(), "Packing small stages must not move their cost to overflow pages");
		assertTrue(footprint.leafPages() + footprint.branchPages() <= 8,
				() -> "64 tiny unpublished stages must use at most eight source leaf and branch pages; observed "
						+ (footprint.leafPages() + footprint.branchPages()) + " for " + footprint.keyValueBytes()
						+ " key/value bytes on "
						+ footprint.pageSize() + "-byte pages: " + footprint.databases());
	}

	private static Footprint footprint(TripleStore triples) throws IOException {
		return triples.getTxnManager().doWithFreshPriority((stack, transaction) -> {
			var database = stack.mallocInt(1);
			E(mdb_dbi_open(transaction, (ByteBuffer) null, 0, database));
			MDBStat statistics = MDBStat.malloc(stack);
			E(mdb_stat(transaction, database.get(0), statistics));
			int pageSize = statistics.ms_psize();
			long catalogLeaves = statistics.ms_leaf_pages();
			long catalogBranches = statistics.ms_branch_pages();
			long catalogOverflow = statistics.ms_overflow_pages();
			var handle = stack.mallocPointer(1);
			E(mdb_cursor_open(transaction, database.get(0), handle));
			long cursor = handle.get(0);
			List<String> names = new ArrayList<>();
			long catalogSourceBytes = 0;
			MDBVal key = MDBVal.malloc(stack);
			MDBVal value = MDBVal.malloc(stack);
			try {
				int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
				while (result == MDB_SUCCESS) {
					byte[] keyBytes = new byte[(int) key.mv_size()];
					Objects.requireNonNull(key.mv_data()).duplicate().get(keyBytes);
					String name = new String(keyBytes, StandardCharsets.UTF_8);
					if (name.startsWith("backup-outbox")) {
						names.add(name);
					} else if (Arrays.equals(LmdbBackupCatalogTestSupport.KEY, keyBytes)) {
						byte[] record = new byte[(int) value.mv_size()];
						Objects.requireNonNull(value.mv_data()).duplicate().get(record);
						LmdbBackupCatalogTestSupport.unpack(record);
						catalogSourceBytes = key.mv_size() + value.mv_size();
					}
					result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
				}
				E(result);
			} finally {
				mdb_cursor_close(cursor);
			}

			// Charge every catalog page when it contains a source record, although RDF indexes share those pages.
			long leaves = catalogSourceBytes == 0 ? 0 : catalogLeaves;
			long branches = catalogSourceBytes == 0 ? 0 : catalogBranches;
			long overflow = catalogSourceBytes == 0 ? 0 : catalogOverflow;
			long entries = catalogSourceBytes == 0 ? 0 : 1;
			long keyValueBytes = catalogSourceBytes;
			Map<String, Long> databases = new LinkedHashMap<>();
			if (catalogSourceBytes != 0) {
				databases.put("[main catalog source]", catalogLeaves);
			}
			for (String name : names) {
				E(mdb_dbi_open(transaction, name, 0, database));
				E(mdb_stat(transaction, database.get(0), statistics));
				assertEquals(pageSize, statistics.ms_psize());
				leaves += statistics.ms_leaf_pages();
				branches += statistics.ms_branch_pages();
				overflow += statistics.ms_overflow_pages();
				entries += statistics.ms_entries();
				databases.put(name, statistics.ms_leaf_pages());
				E(mdb_cursor_open(transaction, database.get(0), handle));
				cursor = handle.get(0);
				try {
					int result = mdb_cursor_get(cursor, key, value, MDB_FIRST);
					while (result == MDB_SUCCESS) {
						keyValueBytes += key.mv_size() + value.mv_size();
						result = mdb_cursor_get(cursor, key, value, MDB_NEXT);
					}
					E(result);
				} finally {
					mdb_cursor_close(cursor);
				}
			}
			return new Footprint(pageSize, leaves, branches, overflow, entries, keyValueBytes, databases);
		});
	}

	private static void assertPublished(LmdbStore store, Path backups, long baseline, UUID generation,
			List<Statement> statements, Path destination) throws IOException {
		List<Path> logs = ((LmdbBackupServiceImpl) store.getBackupService()).exportTransactionLogs(backups, baseline,
				baseline + statements.size(), destination);
		assertEquals(statements.size(), logs.size());
		for (int index = 0; index < statements.size(); index++) {
			ByteArrayOutputStream expected = new ByteArrayOutputStream();
			LmdbBackupDeltaCodec.write(expected, List.of(new Record(true, true, statements.get(index))),
					baseline + index, generation);
			try (var input = new GZIPInputStream(Files.newInputStream(logs.get(index)))) {
				assertArrayEquals(expected.toByteArray(), input.readAllBytes(),
						"Every exported journal must preserve the exact committed record bytes and predecessor");
			}
		}
	}

	private static byte[] stageBytes(Stage stage, Statement statement) throws IOException {
		ByteArrayOutputStream expected = new ByteArrayOutputStream();
		try (DataOutputStream output = new DataOutputStream(expected)) {
			PostCommitBackupPublisher.writeStageHeader(output, stage);
			LmdbBackupDeltaCodec.writeRecords(output, List.of(new Record(true, true, statement)));
		}
		return expected.toByteArray();
	}

	private static Statement statement(int index) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:s:" + index), values.createIRI("urn:p"),
				values.createLiteral("v"));
	}

	private static void add(LmdbStore store, Statement statement) {
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(statement.getSubject(), statement.getPredicate(), statement.getObject());
			connection.commit();
		}
	}

	private static void assertContents(LmdbStore store, List<Statement> statements) {
		try (var connection = store.getConnection()) {
			assertEquals(statements.size(), connection.size());
			for (Statement statement : statements) {
				assertTrue(
						connection.hasStatement(statement.getSubject(), statement.getPredicate(), statement.getObject(),
								false));
			}
		}
	}

	private record Footprint(int pageSize, long leafPages, long branchPages, long overflowPages, long entries,
			long keyValueBytes, Map<String, Long> databases) {
	}
}
